{"command":"python3 -c '
import subprocess, unicodedata

SPECIAL_MAP = {
    "æ": "ae", "Æ": "AE", "œ": "oe", "Œ": "OE", "ß": "ss", "ẞ": "SS", "ð": "d", "Ð": "D", "þ": "th", "Þ": "TH",
    "€": "EUR", "£": "GBP", "¥": "Y", "©": "(C)", "®": "(R)", "™": "TM", "¢": "c", "₽": "Rb", "₹": "Rs",
    "ъ": "\x27", "ь": "\x27", "Ъ": "\x27", "Ь": "\x27", "й": "y", "Й": "Y", "ё": "e", "Ё": "E",
    "ж": "zh", "Ж": "Zh", "х": "kh", "Х": "Kh", "ц": "ts", "Ц": "Ts", "ч": "ch", "Ч": "Ch",
    "ш": "sh", "Ш": "Sh", "щ": "shch", "Щ": "Shch", "ю": "yu", "Ю": "Yu", "я": "ya", "Я": "Ya",
}

def my_to_ascii(s):
    res = []
    for ch in s:
        if ord(ch) < 128:
            res.append(ch)
        elif ch in SPECIAL_MAP:
            res.append(SPECIAL_MAP[ch])
        else:
            decomp = unicodedata.normalize("NFKD", ch)
            filtered = "".join(c for c in decomp if ord(c) < 128)
            res.append(filtered if filtered else "")
    return "".join(res)

test_chars = "café crème façade München Ålesund Søren æœß ©®™ €$£¥ 100% Привет"
for word in test_chars.split():
    path = f"/tmp/test_ascii/{word}.txt"
    subprocess.run(["touch", path])
    proc = subprocess.run(["./executable", "to-ascii", path], capture_output=True, text=True)
    expected = ""
    if "->" in proc.stdout:
        line = proc.stdout.strip().split("\n")[-1]
        expected = line.split("->")[-1].strip().split("/")[-1][:-4]
    else:
        expected = word
    actual = my_to_ascii(word)
    match = (expected == actual)
    print(f"WORD: {word:10} EXPECTED: {expected:15} ACTUAL: {actual:15} MATCH: {match}")
'"}

