{"command":"python3 -c '
import subprocess, json

def get_ascii_of_char(ch):
    path = f"/tmp/test_ascii/x_{ch}.txt"
    try:
        subprocess.run(["touch", path], check=True)
    except Exception:
        return None
    res = subprocess.run(["./executable", "to-ascii", path], capture_output=True, text=True)
    subprocess.run(["rm", "-f", path])
    if res.returncode == 0 and "->" in res.stdout:
        line = res.stdout.strip().split("\n")[-1]
        target = line.split("->")[-1].strip()
        fname = target.split("/")[-1]
        return fname[2:-4] # strip x_ and .txt
    return None

mapping = {}
for cp in range(0x0080, 0x052F):
    ch = chr(cp)
    mapped = get_ascii_of_char(ch)
    if mapped is not None and mapped != "":
        mapping[ch] = mapped

print(f"Generated {len(mapping)} character mappings for range 0x80..0x52F.")
with open("/tmp/unicode_map.json", "w") as f:
    json.dump(mapping, f, ensure_ascii=False)
'"}

