mod unicode_table;

use std::collections::HashMap;
use std::fs;
use std::io::IsTerminal;
use std::path::{Path, PathBuf};
use std::process::exit;

use chrono::Local;
use clap::{Arg, ArgAction, Command};
use regex::Regex;
use serde::{Deserialize, Serialize};
use walkdir::WalkDir;

#[derive(Serialize, Deserialize, Debug, Clone)]
struct Operation {
    source: String,
    target: String,
}

#[derive(Serialize, Deserialize, Debug)]
struct DumpFile {
    date: String,
    operations: Vec<Operation>,
}

#[derive(PartialEq)]
enum ColorMode {
    Always,
    Never,
    Auto,
}

fn build_cli() -> Command {
    let common_options = vec![
        Arg::new("dry-run")
            .short('n')
            .long("dry-run")
            .help("Only show what would be done (default mode)")
            .action(ArgAction::SetTrue)
            .conflicts_with("force"),
        Arg::new("force")
            .short('f')
            .long("force")
            .help("Make actual changes to files")
            .action(ArgAction::SetTrue)
            .conflicts_with("dry-run"),
        Arg::new("backup")
            .short('b')
            .long("backup")
            .help("Generate file backups before renaming")
            .action(ArgAction::SetTrue),
        Arg::new("silent")
            .short('s')
            .long("silent")
            .help("Do not print any information")
            .action(ArgAction::SetTrue),
        Arg::new("color")
            .long("color")
            .help("Set color output mode")
            .default_value("auto")
            .value_parser(["always", "never", "auto"])
            .value_name("COLOR"),
        Arg::new("dump")
            .long("dump")
            .help("Force dumping operations into a file even in dry-run mode")
            .action(ArgAction::SetTrue)
            .conflicts_with("no-dump"),
        Arg::new("dump-prefix")
            .long("dump-prefix")
            .help("Set the dump file prefix")
            .default_value("rnr-")
            .value_name("DUMP_PREFIX"),
        Arg::new("no-dump")
            .long("no-dump")
            .help("Do not dump operations into a file")
            .action(ArgAction::SetTrue)
            .conflicts_with("dump"),
    ];

    let path_options = vec![
        Arg::new("include-dirs")
            .short('D')
            .long("include-dirs")
            .help("Rename matching directories")
            .action(ArgAction::SetTrue),
        Arg::new("recursive")
            .short('r')
            .long("recursive")
            .help("Recursive mode")
            .action(ArgAction::SetTrue),
        Arg::new("max-depth")
            .short('d')
            .long("max-depth")
