    res
}

fn is_hidden(path: &Path) -> bool {
    path.file_name()
        .and_then(|s| s.to_str())
        .map(|s| s.starts_with('.'))
        .unwrap_or(false)
}

fn collect_paths(
    input_paths: &[String],
    recursive: bool,
    max_depth: Option<usize>,
    include_dirs: bool,
    hidden: bool,
) -> Vec<PathBuf> {
    let mut result = Vec::new();

    for input in input_paths {
        let root_path = PathBuf::from(input);
        if !root_path.exists() {
            // Keep path if it doesn't exist so dry run / conflict check handles it
            result.push(root_path);
            continue;
        }

        if root_path.is_file() {
            result.push(root_path);
        } else if root_path.is_dir() {
            if recursive {
                let mut walker = WalkDir::new(&root_path);
                if let Some(depth) = max_depth {
                    walker = walker.max_depth(depth);
                }
                let mut entries: Vec<_> = walker
                    .into_iter()
                    .filter_entry(|e| {
                        if hidden {
                            true
                        } else {
                            if e.depth() == 0 {
                                true
                            } else {
                                !is_hidden(e.path())
                            }
                        }
                    })
                    .filter_map(|e| e.ok())
                    .collect();

                // Sort entries by depth descending so child entries are processed before parents
                entries.sort_by(|a, b| {
                    b.depth()
                        .cmp(&a.depth())
                        .then_with(|| a.path().cmp(b.path()))
                });

                for entry in entries {
                    let p = entry.path().to_path_buf();
                    if entry.file_type().is_file() {
                        result.push(p);
                    } else if entry.file_type().is_dir() {
                        if include_dirs {
                            result.push(p);
                        }
                    }
                }
            } else {
                if include_dirs {
                    result.push(root_path);
                }
            }
        }
    }

    result
}

fn replace_limit_fn(
    re: &Regex,
    haystack: &str,
    replacement: &str,
    limit: usize,
    transform: Option<&str>,
) -> String {
    if limit == 0 {
        re.replace_all(haystack, |caps: &regex::Captures| {
            let mut expanded = String::new();
            caps.expand(replacement, &mut expanded);
            apply_transform(&expanded, transform)
        })
        .to_string()
    } else {
        let mut count = 0;
        re.replace_all(haystack, |caps: &regex::Captures| {
            if count < limit {
                count += 1;
                let mut expanded = String::new();
                caps.expand(replacement, &mut expanded);
                apply_transform(&expanded, transform)
            } else {
                caps.get(0).unwrap().as_str().to_string()
            }
        })
        .to_string()
    }
}

fn apply_transform(s: &str, transform: Option<&str>) -> String {
    match transform {
        Some("upper") => s.to_uppercase(),
        Some("lower") => s.to_lowercase(),
        Some("ascii") => to_ascii_str(s),
        _ => s.to_string(),
    }
}

fn format_operation(source: &str, target: &str, color: bool) -> String {
    if !color {
        return format!("{} -> {}", source, target);
    }

    let gray = "\x1b[38;5;8m";
    let green = "\x1b[32m";
    let bold_red = "\x1b[1;31m";
    let reset = "\x1b[0m";

    let colored_source = format!("{}{}{}", gray, source, reset);

    let target_path = Path::new(target);
    let target_dir = target_path
        .parent()
        .map(|p| p.to_string_lossy().to_string())
        .unwrap_or_default();
    let target_file = target_path
        .file_name()
        .map(|f| f.to_string_lossy().to_string())
        .unwrap_or_default();

    let source_path = Path::new(source);
    let source_file = source_path
        .file_name()
        .map(|f| f.to_string_lossy().to_string())
        .unwrap_or_default();

    let colored_target_dir = if target_dir.is_empty() {
        String::new()
    } else {
        let dir_str = if source.starts_with("./") && !target_dir.starts_with("./") {
            format!("./{}", target_dir)
        } else {
            target_dir
        };
        format!("{}{}/{}\x1b[0m", green, dir_str, reset)
    };

    let colored_filename = lcs_diff_color(&source_file, &target_file, green, bold_red, reset);

    format!(
        "{} -> {}{}",
        colored_source, colored_target_dir, colored_filename
    )
}

fn lcs_diff_color(
    src_filename: &str,
    dst_filename: &str,
    green: &str,
    bold_red: &str,
    reset: &str,
) -> String {
    let src_chars: Vec<char> = src_filename.chars().collect();
    let dst_chars: Vec<char> = dst_filename.chars().collect();
    let m = src_chars.len();
    let n = dst_chars.len();

    let mut dp = vec![vec![0; n + 1]; m + 1];
    for i in 0..m {
        for j in 0..n {
            if src_chars[i] == dst_chars[j] {
                dp[i + 1][j + 1] = dp[i][j] + 1;
            } else {
                dp[i + 1][j + 1] = dp[i + 1][j].max(dp[i][j + 1]);
            }
        }
    }

    let mut is_common = vec![false; n];
    let (mut i, mut j) = (m, n);
    while i > 0 && j > 0 {
        if src_chars[i - 1] == dst_chars[j - 1] {
            is_common[j - 1] = true;
            i -= 1;
            j -= 1;
        } else if dp[i - 1][j] > dp[i][j - 1] {
            i -= 1;
        } else {
            j -= 1;
        }
    }

    let mut res = String::new();
    let mut current_color: Option<&str> = None;

    for (k, &ch) in dst_chars.iter().enumerate() {
        let color = if is_common[k] { green } else { bold_red };
        if current_color != Some(color) {
            res.push_str(color);
            current_color = Some(color);
        }
        res.push(ch);
    }
    if current_color.is_some() {
        res.push_str(reset);
    }
    res
}

fn create_backup(source: &Path) -> std::io::Result<PathBuf> {
    let base_backup = format!("{}.bk", source.display());
    let mut candidate = PathBuf::from(&base_backup);
    let mut counter = 1;

    while candidate.exists() {
        candidate = PathBuf::from(format!("{}.{}", base_backup, counter));
        counter += 1;
    }

    fs::copy(source, &candidate)?;
    Ok(candidate)
}

fn main() {
    let matches = build_cli().get_matches();

    let (subcommand_name, sub_matches) = matches.subcommand().unwrap();

    let force = sub_matches.get_flag("force");
    let dry_run = !force;
    let backup = sub_matches.get_flag("backup");
    let silent = sub_matches.get_flag("silent");
    let color_str = sub_matches.get_one::<String>("color").unwrap().as_str();
    let color_mode = match color_str {
        "always" => ColorMode::Always,
        "never" => ColorMode::Never,
        _ => ColorMode::Auto,
    };
    let use_color = match color_mode {
        ColorMode::Always => true,
        ColorMode::Never => false,
        ColorMode::Auto => std::io::stdout().is_terminal(),
    };

    let dump = sub_matches.get_flag("dump");
    let dump_prefix = sub_matches.get_one::<String>("dump-prefix").unwrap();
    let no_dump = sub_matches.get_flag("no-dump");

    let should_dump = (force && !no_dump) || (dry_run && dump && !no_dump);

    let mut operations: Vec<Operation> = Vec::new();

    if subcommand_name == "regex" {
        let expression = sub_matches.get_one::<String>("expression").unwrap();
        let replacement = sub_matches.get_one::<String>("replacement").unwrap();
        let paths: Vec<String> = sub_matches
            .get_many::<String>("path")
            .unwrap()
            .cloned()
            .collect();
        let limit = sub_matches
            .get_one::<usize>("replace-limit")
            .copied()
            .unwrap_or(0);
        let transform = sub_matches
            .get_one::<String>("replace-transform")
            .map(|s| s.as_str());
        let include_dirs = sub_matches.get_flag("include-dirs");
        let recursive = sub_matches.get_flag("recursive");
        let max_depth = sub_matches.get_one::<usize>("max-depth").copied();
        let hidden = sub_matches.get_flag("hidden");

        let re = match Regex::new(expression) {
            Ok(r) => r,
            Err(e) => {
                let err_msg = if use_color {
                    format!("\x1b[31mError: \x1b[0mBad expression provided\n\n\x1b[31m{}\x1b[0m", e)
                } else {
                    format!("Error: Bad expression provided\n\n{}", e)
                };
                eprintln!("{}", err_msg);
                exit(1);
            }
        };

        let target_paths = collect_paths(&paths, recursive, max_depth, include_dirs, hidden);

        for path_buf in target_paths {
            let path_str = path_buf.to_string_lossy().to_string();
            let file_name = match path_buf.file_name() {
                Some(f) => f.to_string_lossy().to_string(),
                None => continue,
            };

            let new_file_name = replace_limit_fn(&re, &file_name, replacement, limit, transform);
            if new_file_name != file_name {
                let parent = path_buf.parent().unwrap_or_else(|| Path::new(""));
                let target_buf = if parent.as_os_str().is_empty() {
                    PathBuf::from(new_file_name)
                } else {
                    parent.join(new_file_name)
                };
                let target_str = target_buf.to_string_lossy().to_string();

                operations.push(Operation {
                    source: path_str,
                    target: target_str,
                });
            }
        }
    } else if subcommand_name == "to-ascii" {
        let paths: Vec<String> = sub_matches
            .get_many::<String>("path")
            .unwrap()
            .cloned()
            .collect();
        let include_dirs = sub_matches.get_flag("include-dirs");
        let recursive = sub_matches.get_flag("recursive");
        let max_depth = sub_matches.get_one::<usize>("max-depth").copied();
        let hidden = sub_matches.get_flag("hidden");

        let target_paths = collect_paths(&paths, recursive, max_depth, include_dirs, hidden);

        for path_buf in target_paths {
            let path_str = path_buf.to_string_lossy().to_string();
            let file_name = match path_buf.file_name() {
                Some(f) => f.to_string_lossy().to_string(),
                None => continue,
            };

            let new_file_name = to_ascii_str(&file_name);
            if new_file_name != file_name {
                let parent = path_buf.parent().unwrap_or_else(|| Path::new(""));
                let target_buf = if parent.as_os_str().is_empty() {
                    PathBuf::from(new_file_name)
                } else {
                    parent.join(new_file_name)
                };
                let target_str = target_buf.to_string_lossy().to_string();

                operations.push(Operation {
                    source: path_str,
                    target: target_str,
                });
            }
        }
    } else if subcommand_name == "from-file" {
        let dumpfile = sub_matches.get_one::<String>("dumpfile").unwrap();
        let undo = sub_matches.get_flag("undo");

        let content = match fs::read_to_string(dumpfile) {
            Ok(c) => c,
            Err(_) => {
                let err_msg = if use_color {
                    format!("\x1b[31mError: \x1b[0mCannot open/read file {}", dumpfile)
                } else {
                    format!("Error: Cannot open/read file {}", dumpfile)
                };
                eprintln!("{}", err_msg);
                if dry_run && !silent {
                    let header = if use_color {
                        "\x1b[1mThis is a DRY-RUN\x1b[0m"
                    } else {
                        "This is a DRY-RUN"
                    };
                    println!("{}", header);
                }
                exit(1);
            }
        };

        let dump_data: DumpFile = match serde_json::from_str(&content) {
            Ok(d) => d,
            Err(_) => {
                let err_msg = if use_color {
                    format!("\x1b[31mError: \x1b[0mCannot parse JSON file {}", dumpfile)
                } else {
                    format!("Error: Cannot parse JSON file {}", dumpfile)
                };
                eprintln!("{}", err_msg);
                if dry_run && !silent {
                    let header = if use_color {
                        "\x1b[1mThis is a DRY-RUN\x1b[0m"
                    } else {
                        "This is a DRY-RUN"
                    };
                    println!("{}", header);
                }
                exit(1);
            }
        };

        let mut raw_ops = dump_data.operations;
        if undo {
            raw_ops.reverse();
            for op in raw_ops {
                operations.push(Operation {
                    source: op.target,
                    target: op.source,
                });
            }
        } else {
            operations = raw_ops;
        }
    }

    // Perform Conflict Validation (for regex and to-ascii)
    if subcommand_name != "from-file" {
        // 1. Target duplicates check
        let mut target_map: HashMap<String, Vec<String>> = HashMap::new();
        for op in &operations {
            target_map
                .entry(op.target.clone())
                .or_default()
                .push(op.source.clone());
        }

        let mut has_duplicate_targets = false;
        for (target, sources) in &target_map {
            if sources.len() > 1 {
                has_duplicate_targets = true;
                break;
            }
        }

        if has_duplicate_targets {
            if dry_run && !silent {
                let header = if use_color {
                    "\x1b[1mThis is a DRY-RUN\x1b[0m"
                } else {
                    "This is a DRY-RUN"
                };
                println!("{}", header);
            }

            let err_header = if use_color {
                "\x1b[31mError: \x1b[0mFiles will have the same name\n"
            } else {
                "Error: Files will have the same name\n"
            };
            eprintln!("{}", err_header);

            for op in &operations {
                if let Some(sources) = target_map.get(&op.target) {
                    if sources.len() > 1 {
                        eprintln!("{}->{}", op.source, op.target);
                    }
                }
            }
            eprintln!();
            exit(1);
        }

        // 2. Existing path check
        for op in &operations {
            if op.source != op.target && Path::new(&op.target).exists() {
                if dry_run && !silent {
                    let header = if use_color {
                        "\x1b[1mThis is a DRY-RUN\x1b[0m"
                    } else {
                        "This is a DRY-RUN"
                    };
                    println!("{}", header);
                }

                let err_msg = if use_color {
                    format!(
                        "\x1b[31mError: \x1b[0mConflict with existing path {} -> {}",
                        op.source, op.target
                    )
                } else {
                    format!(
                        "Error: Conflict with existing path {} -> {}",
                        op.source, op.target
                    )
                };
                eprintln!("{}", err_msg);
                exit(1);
            }
        }
    }

    if dry_run {
        if !silent {
            let header = if use_color {
                "\x1b[1mThis is a DRY-RUN\x1b[0m"
            } else {
                "This is a DRY-RUN"
            };
            println!("{}", header);

            for op in &operations {
                println!("{}", format_operation(&op.source, &op.target, use_color));
            }
        }
    } else if force {
        for op in &operations {
            if backup {
                let src_path = Path::new(&op.source);
                if src_path.exists() {
                    match create_backup(src_path) {
                        Ok(bk_path) => {
                            if !silent {
                                let bk_str = bk_path.to_string_lossy();
                                if use_color {
                                    println!(
                                        "\x1b[1mInfo: \x1b[0m Backup created - \x1b[38;5;8m{} -> {}\x1b[0m",
                                        op.source, bk_str
                                    );
                                } else {
                                    println!(
                                        "Info:  Backup created - {} -> {}",
                                        op.source, bk_str
                                    );
                                }
                            }
                        }
                        Err(e) => {
                            eprintln!("Error: Cannot create backup for {}\n{}", op.source, e);
                            exit(1);
                        }
                    }
                }
            }

            if let Err(e) = fs::rename(&op.source, &op.target) {
                let err_msg = if use_color {
                    format!(
                        "\x1b[31mError: \x1b[0mCannot rename {} -> {}\n{}",
                        op.source, op.target, e
                    )
                } else {
                    format!("Error: Cannot rename {} -> {}\n{}", op.source, op.target, e)
                };
                eprintln!("{}", err_msg);
                exit(1);
            }

            if !silent {
                println!("{}", format_operation(&op.source, &op.target, use_color));
            }
        }
    }

    if should_dump {
        let now = Local::now();
        let json_date = now.format("%Y-%m-%d %H:%M:%S").to_string();
        let file_date = now.format("%Y-%m-%d_%H%M%S").to_string();

        let dump_filename = format!("{}{}.json", dump_prefix, file_date);

        let dump_data = DumpFile {
            date: json_date,
            operations: operations.clone(),
        };

        if let Ok(json_str) = serde_json::to_string_pretty(&dump_data) {
            let _ = fs::write(&dump_filename, json_str);
        }
    }
}
EOF"}
